// StructType is a schema ref, e.g. schema.ref("Struct")
// Case-class member names (n, s) must match the GraphQL field names.

import grackle.generic._
import StarWarsMapping.semiauto._

sealed trait Character {
  def id: String
  def name: Option[String]
  def appearsIn: Option[List[Episode.Value]]
  def friends: Option[List[String]]
}
object Character {
  implicit val cursorBuilder: CursorBuilder[Character] =
    deriveInterfaceCursorBuilder[Character](CharacterType)
}

case class Human(
  id: String, name: Option[String],
  appearsIn: Option[List[Episode.Value]],
  friends: Option[List[String]], homePlanet: Option[String]
) extends Character
object Human {
  implicit val cursorBuilder: CursorBuilder[Human] =
    deriveObjectCursorBuilder[Human](HumanType).transformField("friends")(resolveFriends)
}

def resolveFriends(c: Character): Result[Option[List[Character]]] =
  c.friends match {
    case None => None.success
    case Some(ids) =>
      ids.traverse(id => characters.find(_.id == id).toResultOrError(s"Bad id '$id'"))
         .map(_.some)
  }

// friends in the model is Option[List[String]] (ids), but the schema
// declares friends: [Character!]; transformField bridges the gap:
deriveObjectCursorBuilder[Human](HumanType).transformField("friends")(resolveFriends)

import io.circe.Encoder
import grackle.generic._
import MovieMapping.semiauto._

sealed trait Genre
object Genre {
  case object Drama extends Genre; case object Action extends Genre; case object Comedy extends Genre
  implicit val genreEncoder: Encoder[Genre] =
    Encoder[String].contramap { case Drama => "DRAMA"; case Action => "ACTION"; case Comedy => "COMEDY" }
  implicit val cursorBuilder: CursorBuilder[Genre] =
    CursorBuilder.deriveLeafCursorBuilder[Genre](GenreType)
}

case class Movie(id: java.util.UUID, title: String, genre: Genre,
                 releaseDate: java.time.LocalDate /* ... */)
object Movie {
  implicit val cursorBuilder: CursorBuilder[Movie] = deriveObjectCursorBuilder[Movie](MovieType)
}

object StarWarsMapping extends GenericMapping[IO] {
  val schema = schema""" type Query { hero(episode: Episode!): Character! ... } ... """
  val QueryType = schema.ref("Query")
  val CharacterType = schema.ref("Character")
  // ... HumanType, DroidType, EpisodeType

  val typeMappings = List(
    ObjectMapping(
      tpe = QueryType,
      fieldMappings = List(
        GenericField("hero", characters),
        GenericField("character", characters),
        GenericField("human", characters.collect { case h: Human => h }),
        GenericField("droid", characters.collect { case d: Droid => d })
      )
    )
  )
}

class GenericEffectMapping[F[_]: Sync](ref: SignallingRef[F, Int]) extends GenericMapping[F] {
  import semiauto._
  case class Struct(n: Int, s: String)
  object Struct { implicit val cb: CursorBuilder[Struct] = deriveObjectCursorBuilder[Struct](StructType) }

  val typeMappings = List(
    ObjectMapping(
      tpe = QueryType,
      fieldMappings = List(
        RootEffect.computeCursor("foo")((p, e) =>
          ref.update(_ + 1).as(genericCursor(p, e, Struct(42, "hi"))))
      )
    )
  )
}

